    elif applicant.parent_income == 'medium':
        score += 2
    elif applicant.parent_income == 'low':
        score += 1

    # Calculate Parents' Degree score
    parent_degree_score = {'PhD': 3, 'master': 2, 'bachelor': 1, 'non-degree': 0}  
    score += parent_degree_score.get(applicant.parent_degree, 0)

    # Calculate Recommendation Letters score
    if applicant.recommendation_letters == 'strong':
        score += 2
    elif applicant.recommendation_letters == 'medium':
        score += 1

    # Calculate Relevant Experience score
    if applicant.relevant_experience >= 2:  # assuming any number of years equals or exceeds 2
        score += 2
    elif applicant.relevant_experience >= 1:
        score += 1

