    elif applicant.GPA >= 3.0:
        score += 1

    if applicant.parents_degree in ["bachelor", "master", "PhD"]:
        score += 1
    elif applicant.parents_degree == "non-degree":
        score += 1

    if applicant.parents_income == "high":
        score += 1

    if applicant.personal_statement == "high quality":
        score += 2

    # Consider relevance experience as a factor of a maximum 2 points (as it is the highest)
    # Also, relevance experience won't bring any advantage to a student if he/she doesn't have any skills set
    score += max(2 - skills_score, 0) + applicant.relevant_experience

